//! AC1: schema 3 and the v1 -> v2 -> v3 migration match Python.
//!
//! The expected schema and the migrated rows are generated by
//! `tests/generate_rust_store_fixture.py` from the REAL Python
//! `share.store.ShareStore`; this test only reads the fixture and compares.

use std::path::PathBuf;

use rusqlite::Connection;
use serde_json::{json, Value};
use um_store::ShareStore;

fn fixture() -> Value {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../..")
        .join("tests/fixtures/rust_store_rev1.json");
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

fn test_key() -> Vec<u8> {
    (0..32).collect()
}

fn normalize_sql(sql: &str) -> String {
    sql.split_whitespace().collect::<Vec<_>>().join(" ")
}

fn schema_objects(connection: &Connection) -> Value {
    let mut statement = connection
        .prepare(
            "SELECT type,name,tbl_name,sql FROM sqlite_master WHERE sql IS NOT NULL ORDER BY type,name",
        )
        .unwrap();
    let rows = statement
        .query_map([], |row| {
            Ok((
                row.get::<_, String>(0)?,
                row.get::<_, String>(1)?,
                row.get::<_, String>(3)?,
            ))
        })
        .unwrap();
    let mut objects = serde_json::Map::new();
    for row in rows {
        let (kind, name, sql) = row.unwrap();
        objects.insert(format!("{kind}:{name}"), json!(normalize_sql(&sql)));
    }
    Value::Object(objects)
}

fn table_info(connection: &Connection) -> Value {
    let mut columns = serde_json::Map::new();
    for table in ["meta", "keys", "ops", "configgen", "security"] {
        let mut statement = connection
            .prepare(&format!("PRAGMA table_info({table})"))
            .unwrap();
        let rows = statement
            .query_map([], |row| {
                Ok(json!([
                    row.get::<_, String>(1)?,
                    row.get::<_, String>(2)?,
                    row.get::<_, i64>(3)?,
                    row.get::<_, Option<String>>(4)?,
                    row.get::<_, i64>(5)?,
                ]))
            })
            .unwrap();
        let entries: Vec<Value> = rows.map(Result::unwrap).collect();
        columns.insert(table.to_string(), Value::Array(entries));
    }
    Value::Object(columns)
}

fn meta_rows(connection: &Connection) -> Value {
    let mut statement = connection
        .prepare("SELECT key,value FROM meta ORDER BY key")
        .unwrap();
    let rows = statement
        .query_map([], |row| {
            Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?))
        })
        .unwrap();
    let mut map = serde_json::Map::new();
    for row in rows {
        let (key, value) = row.unwrap();
        map.insert(key, json!(value));
    }
    Value::Object(map)
}

fn configgen_rows(connection: &Connection) -> Value {
    let mut statement = connection
        .prepare("SELECT schema_version,config_generation,applied_generation FROM configgen")
        .unwrap();
    let rows = statement
        .query_map([], |row| {
            Ok(json!({
                "schema_version": row.get::<_, i64>(0)?,
                "config_generation": row.get::<_, i64>(1)?,
                "applied_generation": row.get::<_, i64>(2)?,
            }))
        })
        .unwrap();
    Value::Array(rows.map(Result::unwrap).collect())
}

fn index_rows(connection: &Connection) -> Value {
    let mut statement = connection.prepare("PRAGMA index_list(keys)").unwrap();
    let rows = statement
        .query_map([], |row| {
            Ok(json!([row.get::<_, String>(1)?, row.get::<_, i64>(2)?]))
        })
        .unwrap();
    Value::Array(rows.map(Result::unwrap).collect())
}

fn legacy_row(connection: &Connection) -> Value {
    let mut statement = connection
        .prepare(
            "SELECT key_id,name,secret_version,masked_key,enabled,max_concurrency,row_version,deleted_at,secret_blob,secret_algo FROM keys",
        )
        .unwrap();
    let rows = statement
        .query_map([], |row| {
            Ok(json!({
                "key_id": row.get::<_, String>(0)?,
                "name": row.get::<_, String>(1)?,
                "secret_version": row.get::<_, i64>(2)?,
                "masked_key": row.get::<_, String>(3)?,
                "enabled": row.get::<_, i64>(4)?,
                "max_concurrency": row.get::<_, i64>(5)?,
                "row_version": row.get::<_, i64>(6)?,
                "deleted_at": row.get::<_, Option<String>>(7)?,
                "secret_blob": row.get::<_, Option<Vec<u8>>>(8)?,
                "secret_algo": row.get::<_, Option<String>>(9)?,
            }))
        })
        .unwrap();
    Value::Array(rows.map(Result::unwrap).collect())
}

#[test]
fn a_fresh_store_creates_the_python_schema_3() {
    let fixture = fixture();
    let directory = tempfile::tempdir().unwrap();
    let path = directory.path().join("share-store.db");
    let store = ShareStore::open_with_key(&path, test_key()).unwrap();
    let connection = store.connection();
    let expected = &fixture["schema"];
    assert_eq!(
        schema_objects(connection),
        expected["objects"],
        "sqlite_master objects differ from Python"
    );
    assert_eq!(
        table_info(connection),
        expected["columns"],
        "declared columns differ from Python"
    );
    assert_eq!(
        meta_rows(connection),
        expected["meta"],
        "meta rows differ from Python"
    );
    assert_eq!(
        configgen_rows(connection),
        expected["configgen"],
        "configgen rows differ from Python"
    );
    assert_eq!(
        index_rows(connection),
        expected["indexes"],
        "keys indexes differ from Python"
    );
    assert_eq!(um_store::schema::SCHEMA_VERSION, 3);
    assert_eq!(um_store::schema::PROJECTION_SCHEMA_VERSION, 2);
}

#[test]
fn a_schema_1_store_migrates_like_python_without_touching_key_data() {
    let fixture = fixture();
    let directory = tempfile::tempdir().unwrap();
    let path = directory.path().join("migrated.db");
    let connection = Connection::open(&path).unwrap();
    connection
        .execute_batch(fixture["migration"]["setup_sql"].as_str().unwrap())
        .unwrap();
    drop(connection);
    let store = ShareStore::open_with_key(&path, test_key()).unwrap();
    let connection = store.connection();
    let expected = &fixture["migration"];
    assert_eq!(
        table_info(connection),
        expected["columns"],
        "migrated columns differ from Python"
    );
    assert_eq!(
        meta_rows(connection),
        expected["meta"],
        "migrated meta differs from Python"
    );
    assert_eq!(
        configgen_rows(connection),
        expected["configgen"],
        "migrated configgen differs from Python"
    );
    assert_eq!(
        legacy_row(connection),
        expected["legacy_row"],
        "migrated key rows differ from Python"
    );
}

#[test]
fn an_unsupported_schema_version_is_refused_instead_of_rewritten() {
    let directory = tempfile::tempdir().unwrap();
    let path = directory.path().join("unsupported.db");
    let connection = Connection::open(&path).unwrap();
    connection
        .execute_batch(
            "CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);\
             INSERT INTO meta(key,value) VALUES('schema_version','99');",
        )
        .unwrap();
    drop(connection);
    let error = match ShareStore::open_with_key(&path, test_key()) {
        Ok(_) => panic!("an unsupported schema version must be refused"),
        Err(error) => error,
    };
    assert_eq!(error.kind(), "StoreError");
    assert!(
        error.message().contains("unsupported schema_version 99"),
        "unexpected message: {}",
        error.message()
    );
}
